using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for maximum throughput on large arrays.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (values.Length == 1)
            return (values[0], values[0]);

        // Use 512-bit path if available and array is large enough
        if (Vector512.IsHardwareAccelerated && values.Length >= Vector512<float>.Count * 4)
            return FindMinMax512(values);

        // Use 256-bit path if available and array is large enough
        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count * 4)
            return FindMinMax256(values);

        // Use portable Vector<T> path for other SIMD widths
        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count * 4)
            return FindMinMaxVector(values);

        return FindMinMaxScalar(values);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMax512(ReadOnlySpan<float> values)
    {
        ref float start = ref MemoryMarshal.GetReference(values);
        int count = values.Length;
        int vectorSize = Vector512<float>.Count;

        var vMin0 = Vector512.LoadUnsafe(ref start);
        var vMax0 = vMin0;
        var vMin1 = vMin0;
        var vMax1 = vMax0;

        int i = vectorSize;
        int limit = count - vectorSize * 2 + 1;

        // Process two vectors per iteration to hide latency
        for (; i < limit; i += vectorSize * 2)
        {
            var v0 = Vector512.LoadUnsafe(ref start, (nuint)i);
            var v1 = Vector512.LoadUnsafe(ref start, (nuint)(i + vectorSize));
            vMin0 = Vector512.Min(vMin0, v0);
            vMax0 = Vector512.Max(vMax0, v0);
            vMin1 = Vector512.Min(vMin1, v1);
            vMax1 = Vector512.Max(vMax1, v1);
        }

        // Handle remaining full vectors
        for (; i <= count - vectorSize; i += vectorSize)
        {
            var v = Vector512.LoadUnsafe(ref start, (nuint)i);
            vMin0 = Vector512.Min(vMin0, v);
            vMax0 = Vector512.Max(vMax0, v);
        }

        // Merge the two accumulators
        vMin0 = Vector512.Min(vMin0, vMin1);
        vMax0 = Vector512.Max(vMax0, vMax1);

        // Reduce to scalar
        float min = HorizontalMin512(vMin0);
        float max = HorizontalMax512(vMax0);

        // Handle tail elements
        for (; i < count; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMax256(ReadOnlySpan<float> values)
    {
        ref float start = ref MemoryMarshal.GetReference(values);
        int count = values.Length;
        int vectorSize = Vector256<float>.Count;

        var vMin0 = Vector256.LoadUnsafe(ref start);
        var vMax0 = vMin0;
        var vMin1 = vMin0;
        var vMax1 = vMax0;

        int i = vectorSize;
        int limit = count - vectorSize * 2 + 1;

        for (; i < limit; i += vectorSize * 2)
        {
            var v0 = Vector256.LoadUnsafe(ref start, (nuint)i);
            var v1 = Vector256.LoadUnsafe(ref start, (nuint)(i + vectorSize));
            vMin0 = Vector256.Min(vMin0, v0);
            vMax0 = Vector256.Max(vMax0, v0);
            vMin1 = Vector256.Min(vMin1, v1);
            vMax1 = Vector256.Max(vMax1, v1);
        }

        for (; i <= count - vectorSize; i += vectorSize)
        {
            var v = Vector256.LoadUnsafe(ref start, (nuint)i);
            vMin0 = Vector256.Min(vMin0, v);
            vMax0 = Vector512.Max(vMax0, v);
        }

        vMin0 = Vector256.Min(vMin0, vMin1);
        vMax0 = Vector256.Max(vMax0, vMax1);

        float min = HorizontalMin256(vMin0);
        float max = HorizontalMax256(vMax0);

        for (; i < count; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining | MethodImplOptions.AggressiveOptimization)]
    private static (float Min, float Max) FindMinMaxVector(ReadOnlySpan<float> values)
    {
        ref float start = ref MemoryMarshal.GetReference(values);
        int count = values.Length;
        int vectorSize = Vector<float>.Count;

        var vMin = new Vector<float>(values);
        var vMax = vMin;

        int i = vectorSize;
        for (; i <= count - vectorSize; i += vectorSize)
        {
            var v = new Vector<float>(values.Slice(i));
            vMin = Vector.Min(vMin, v);
            vMax = Vector.Max(vMax, v);
        }

        float min = vMin[0];
        float max = vMax[0];
        for (int j = 1; j < vectorSize; j++)
        {
            if (vMin[j] < min) min = vMin[j];
            if (vMax[j] > max) max = vMax[j];
        }

        for (; i < count; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMin512(Vector512<float> v)
    {
        var lo = v.GetLower();
        var hi = v.GetUpper();
        var min256 = Vector256.Min(lo, hi);
        return HorizontalMin256(min256);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMax512(Vector512<float> v)
    {
        var lo = v.GetLower();
        var hi = v.GetUpper();
        var max256 = Vector256.Max(lo, hi);
        return HorizontalMax256(max256);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMin256(Vector256<float> v)
    {
        var lo = v.GetLower();
        var hi = v.GetUpper();
        var min128 = Vector128.Min(lo, hi);
        return HorizontalMin128(min128);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMax256(Vector256<float> v)
    {
        var lo = v.GetLower();
        var hi = v.GetUpper();
        var max128 = Vector128.Max(lo, hi);
        return HorizontalMax128(max128);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMin128(Vector128<float> v)
    {
        // [a, b, c, d] -> min across all 4 lanes
        var shuf1 = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        var min1 = Vector128.Min(v, shuf1);
        var shuf2 = Vector128.Shuffle(min1, Vector128.Create(1, 0, 3, 2));
        var min2 = Vector128.Min(min1, shuf2);
        return min2.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMax128(Vector128<float> v)
    {
        var shuf1 = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        var max1 = Vector128.Max(v, shuf1);
        var shuf2 = Vector128.Shuffle(max1, Vector128.Create(1, 0, 3, 2));
        var max2 = Vector128.Max(max1, shuf2);
        return max2.ToScalar();
    }
}

